import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import backgroundImage from "../Img/order5.jpg";

const AddOrder = () => {
    // ... (Your state, handleChange, sendData, and handleBackToHome functions remain the same)

    return (
        <div
            style={{
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                minHeight: "100vh",
                backgroundColor: "#f0f0f0",
                backgroundImage: `url(${backgroundImage})`,
                backgroundSize: "cover",
                backgroundRepeat: "no-repeat",
                backgroundBlendMode: "multiply",
            }}
        >
            <div
                style={{
                    backgroundColor: "rgba(255, 255, 255, 0.7)",
                    padding: "20px",
                    borderRadius: "10px",
                    boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
                    width: "100%",
                    maxWidth: "600px",
                    boxSizing: "border-box",
                }}
            >
                <h2 style={{ color: "#8B0000", fontWeight: "bold", textAlign: "center", marginBottom: "20px" }}>
                    Add Order
                </h2>
                <form onSubmit={sendData} style={{ width: "100%" }}>
                    {/* ... (Your form fields remain the same) */}
                    <button
                        type="submit"
                        style={{
                            backgroundColor: "#b30000",
                            color: "white",
                            padding: "10px 20px",
                            border: "none",
                            borderRadius: "5px",
                            cursor: "pointer",
                            fontSize: "16px",
                            marginBottom: "10px",
                        }}
                    >
                        Submit
                    </button>
                </form>
                <button
                    onClick={handleBackToHome}
                    style={{
                        backgroundColor: "#b30000",
                        color: "white",
                        padding: "10px 20px",
                        border: "none",
                        borderRadius: "5px",
                        cursor: "pointer",
                        fontSize: "16px",
                        width: "auto", // Change width to auto
                        marginTop: "10px", // Add margin to separate from the submit button
                    }}
                >
                    Back to Home
                </button>
            </div>
        </div>
    );
};

export default AddOrder;
